"""
Prepare Ground Truth with Source Provenance
============================================
Parses ``HumanTranslations_de-fr-en.csv`` to determine which of the three
language translations per inscription is the *genuine* human translation and
which two were generated by Google Gemini.

Produces ``data/testset/human-translations-testset.csv`` with an additional
``ref_source`` column:

* ``human``  — the first translation listed for each inscription (the real one)
* ``gemini`` — the remaining two translations generated by Gemini

This enriched file replaces the old version (a backup is created first).
"""

import csv
import os
import shutil
from datetime import datetime

BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
RAW_CSV = os.path.join(BASE_DIR, "data", "HumanTranslations_de-fr-en.csv")
TESTSET_DIR = os.path.join(BASE_DIR, "data", "testset")
OUTPUT_CSV = os.path.join(TESTSET_DIR, "human-translations-testset.csv")
FILTERED_TESTSET = os.path.join(TESTSET_DIR, "filtered-testset.csv")


def parse_raw_translations(path):
    """Parse the 3-row-group CSV and return enriched records.

    Returns
    -------
    list[dict]
        Each dict has keys: edcs_id, Übersetzung, Sprache, ref_source
    """
    records = []

    with open(path, "r", encoding="utf-8") as f:
        reader = csv.reader(f)
        header = next(reader)  # skip header

        current_id = None
        group = []  # list of (lang, text) tuples within one inscription

        for row in reader:
            raw_id = row[0].strip() if len(row) > 0 else ""
            text = row[1].strip() if len(row) > 1 else ""
            lang = row[2].strip() if len(row) > 2 else ""

            if not lang or not text:
                continue

            if raw_id:
                # Flush previous group
                if current_id and group:
                    _flush_group(current_id, group, records)
                current_id = raw_id
                group = [(lang, text)]
            else:
                group.append((lang, text))

        # Flush last group
        if current_id and group:
            _flush_group(current_id, group, records)

    return records


def _flush_group(edcs_id, group, records):
    """Add records from one inscription group (3 rows) to the list.

    The first entry is the human translation; the rest are gemini.
    """
    # Normalise EDCS ID: strip leading zeros for consistency with testset
    try:
        edcs_id_norm = str(int(edcs_id))
    except ValueError:
        edcs_id_norm = edcs_id

    for i, (lang, text) in enumerate(group):
        records.append({
            "edcs_id": edcs_id_norm,
            "Übersetzung": text,
            "Sprache": lang,
            "ref_source": "human" if i == 0 else "gemini",
        })


def load_testset_edcs_ids(path):
    """Return the set of numeric EDCS IDs from filtered-testset.csv."""
    ids = set()
    with open(path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            raw = row["edcs_id"].replace("EDCS-", "")
            try:
                ids.add(str(int(raw)))
            except ValueError:
                ids.add(raw)
    return ids


def main():
    print("=" * 70)
    print("Prepare Ground Truth – ref_source enrichment")
    print("=" * 70)

    if not os.path.exists(RAW_CSV):
        print(f"ERROR: Raw CSV not found at {RAW_CSV}")
        return 1

    # Parse the raw 3-row-group CSV
    records = parse_raw_translations(RAW_CSV)
    print(f"Parsed {len(records)} translation records from raw CSV.")

    # Filter to only those EDCS IDs present in the testset
    testset_ids = load_testset_edcs_ids(FILTERED_TESTSET)
    records = [r for r in records if r["edcs_id"] in testset_ids]
    print(f"After filtering to testset IDs: {len(records)} records "
          f"({len(testset_ids)} testset inscriptions).")

    # Statistics
    source_counts = {}
    lang_counts = {}
    for r in records:
        source_counts[r["ref_source"]] = source_counts.get(r["ref_source"], 0) + 1
        key = (r["Sprache"], r["ref_source"])
        lang_counts[key] = lang_counts.get(key, 0) + 1

    print(f"\n  ref_source distribution: {source_counts}")
    print("  Per language × source:")
    for (lang, src), count in sorted(lang_counts.items()):
        print(f"    {lang} / {src}: {count}")

    # Backup existing file
    if os.path.exists(OUTPUT_CSV):
        backup = OUTPUT_CSV + f".bak.{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        shutil.copy2(OUTPUT_CSV, backup)
        print(f"\n  Backed up existing file → {os.path.basename(backup)}")

    # Write enriched CSV
    os.makedirs(TESTSET_DIR, exist_ok=True)
    with open(OUTPUT_CSV, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=["edcs_id", "Übersetzung", "Sprache", "ref_source"])
        writer.writeheader()
        writer.writerows(records)

    print(f"\n✓ Written {len(records)} records to {OUTPUT_CSV}")
    print(f"  (with new 'ref_source' column: human / gemini)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
